ON CONFLICT (id) DO NOTHING;

INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "李茂庄", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷259景福元年条所见人物：李茂庄。", "biography": null, "status": "draft", "id": "404cb408-7abf-5c26-b4b6-2ecc0b4a90c0"}, {"name": "钱镠", "aliases": [], "era": "唐末五代十国", "birth_year": null, "death_year": null, "description": "据《资治通鉴》，907年在“钱氏军队攻取温州，卢佶被杀”中为发令者。", "biography": null, "status": "draft", "id": "d61d1f96-7af5-5367-8be8-7a25ee7c85ae"}, {"name": "张雄", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256光启二年条所见人物：张雄。", "biography": null, "status": "draft", "id": "c143e925-2fd8-5be6-abed-b89d550f0724"}, {"name": "冯弘铎", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256光启二年条所见人物：冯弘铎。", "biography": null, "status": "draft", "id": "7b1519f3-16d0-5251-a7f9-bf583e8dc0c9"}, {"name": "李茂贞", "aliases": [], "era": "唐末五代十国", "birth_year": null, "death_year": null, "description": "据《资治通鉴》，907年在“岐王在唐亡后开府置百官”中为开府者。", "biography": null, "status": "draft", "id": "af9a00d1-c748-5b5f-9175-1af19530d83d"}, {"name": "杜让能", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256光启二年条所见人物：杜让能。", "biography": null, "status": "draft", "id": "e3eae55f-2032-5c76-905f-e480ad32ea69"}, {"name": "李杰", "aliases": ["李敏", "唐昭宗"], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷257文德元年条所见人物：李杰。", "biography": null, "status": "draft", "id": "48935190-c754-5bda-bdcd-382c77cb2de0"}, {"name": "杨复恭", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256中和四年条所见人物：杨复恭。", "biography": null, "status": "draft", "id": "d84e65f4-4bf5-58ad-a8c6-d69729edbc51"}, {"name": "崔昭纬", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷258大顺二年条所见人物：崔昭纬。", "biography": null, "status": "draft", "id": "99370461-a1dd-57da-a64e-c76fb6ea7ba7"}, {"name": "西门君遂", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷258大顺二年条所见人物：西门君遂。", "biography": null, "status": "draft", "id": "ee5a7388-72a2-5742-ad8e-a61393243757"}, {"name": "郑延昌", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷259景福元年条所见人物：郑延昌。", "biography": null, "status": "draft", "id": "33cc9170-06f5-5723-acfc-e8a8f3f1016e"}, {"name": "李嗣周", "aliases": ["嗣覃王嗣周", "覃王嗣周"], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷259景福二年条所见人物：李嗣周。", "biography": null, "status": "draft", "id": "cd54b837-2e61-52c0-82bc-924fef2ce526"}, {"name": "李鐬", "aliases": ["李钅岁"], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷259景福二年条所见人物：李鐬。", "biography": null, "status": "draft", "id": "6270015b-5238-5512-9a8e-e74b32408778"}, {"name": "杨行密", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷257光启三年条所见人物：杨行密。", "biography": null, "status": "draft", "id": "ad75628e-5958-5672-9403-eb349ca77e6e"}, {"name": "田頵", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷255中和四年条记载的田頵，在此段中为击退进攻者。", "biography": null, "status": "draft", "id": "c59b24ec-67c0-5ac6-aaaf-4908d96913b9"}, {"name": "裴枢", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷259景福二年条所见人物：裴枢。", "biography": null, "status": "draft", "id": "657419cc-9699-5e62-9003-8e27dd3f6fc4"}, {"name": "陶雅", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷255中和四年条记载的陶雅，在此段中为领兵及摄刺史。", "biography": null, "status": "draft", "id": "37adebe7-ba16-564c-bfb9-bb1b88712f96"}, {"name": "朱温", "aliases": ["朱全忠", "朱晃", "梁太祖"], "era": "五代十国", "birth_year": null, "death_year": 912, "description": "后梁建立者。907年在大梁称帝，912年在宫廷政变中被杀。", "biography": "后梁建立者。907年在大梁称帝，912年在宫廷政变中被杀。", "status": "draft", "id": "0555e455-34d4-54ef-b93e-b0e6425018ab"}, {"name": "庞师古", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷255中和四年条记载的庞师古，在此段中为击退者。", "biography": null, "status": "draft", "id": "c4c8f403-d8b1-5c64-973d-1fe7b20adcf3"}, {"name": "朱瑾", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256中和四年条所见人物：朱瑾。", "biography": null, "status": "draft", "id": "e4226d41-278e-53c7-9e01-7e3572231e8e"}, {"name": "李存孝", "aliases": ["安敬思"], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷255中和四年条记载的李存孝，在此段中为李克用养子。", "biography": null, "status": "draft", "id": "d25efb4e-74a3-5bab-b1e4-a79cee0716c3"}, {"name": "李存信", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷255中和四年条记载的李存信，在此段中为李克用养子。", "biography": null, "status": "draft", "id": "31ad8087-ed47-5400-bf8a-47f2edb81920"}, {"name": "孙考老", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷259景福二年条所见人物：孙考老。", "biography": null, "status": "draft", "id": "63f0f5b5-aa14-57ea-a439-93311d97a3d3"}, {"name": "李克用", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": 908, "description": "河东晋王，李存勖之父。908年去世，临终命李存勖继承军府。此处的晋不等于后来的后晋。", "biography": "河东晋王，李存勖之父。908年去世，临终命李存勖继承军府。此处的晋不等于后来的后晋。", "status": "draft", "id": "04af206e-fa86-581c-86b9-87a78a8d59a5"}, {"name": "袁奉韬", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷258龙纪元年条所见人物：袁奉韬。", "biography": null, "status": "draft", "id": "1f3a2064-8efb-545e-881e-8d2d8bad2f0b"}, {"name": "邓季筠", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷258大顺元年条所见人物：邓季筠。", "biography": null, "status": "draft", "id": "35e536de-74c3-5810-bcde-8670471465f0"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
SELECT id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status FROM jsonb_populate_recordset(NULL::public.event, '[{"title": "李茂庄加同平章事", "start_year": 893, "end_year": 893, "time_original": "893年七月条；具体日未载", "dynasty": "唐", "description": "天雄节度使李茂庄加同平章事。", "phases": [], "location_name": "天雄", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "911f05b4-9e8c-50ff-815e-389aae827dfe"}, {"title": "钱镠发民夫军士筑杭州罗城", "start_year": 893, "end_year": 893, "time_original": "893年七月条；具体起讫未载", "dynasty": "唐", "description": "钱镠征发民夫二十万及十三都军士修筑杭州外城，书载周长七十里。", "phases": [], "location_name": "杭州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "47a56f1e-5587-5dab-9734-fb6b9a034415"}, {"title": "张雄卒，冯弘铎接升州刺史", "start_year": 893, "end_year": 893, "time_original": "893年七月条；具体日未载", "dynasty": "唐", "description": "升州刺史张雄去世，冯弘铎继任刺史。", "phases": [], "location_name": "升州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "7beb9393-c9f0-5328-8442-e71a70c09d4c"}, {"title": "李茂贞上表及书杜让能，言辞激怒昭宗", "start_year": 893, "end_year": 893, "time_original": "893年七月至八月出兵谋议前；具体日未载", "dynasty": "唐", "description": "李茂贞上表、写信给杜让能，言语不逊。昭宗想讨他，李又上表讥朝廷不能保护元舅、不能诛杨复恭，称朝廷只观强弱不计是非、随强弱施恩刑，并以军情易变、百姓受祸及乘舆将逃往何处等语相逼。", "phases": [], "location_name": "京师、凤翔", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "6a3a9ab4-aeee-5eac-9857-a8ddbd5329c7"}, {"title": "昭宗决讨李茂贞，杜让能谏不宜并承命", "start_year": 893, "end_year": 893, "time_original": "893年；讨伐谋议期间，具体日未载", "dynasty": "唐", "description": "昭宗决定讨李茂贞，命杜让能专掌调兵食。杜劝茂贞近国门、不宜构怨败后无及，建议群臣共力；昭宗说不愿坐视王室衰弱，用兵委诸王、成败不责杜，并以元辅之位要求其任事。杜说明非避事，忧时势不能及日后遭罪，仍奉诏愿以死继之。", "phases": [], "location_name": "京师、中书", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "180ed8d1-edd1-5f93-a9ea-ae66ed8e12d9"}, {"title": "杜让能留中书月余调度，崔昭纬泄二镇", "start_year": 893, "end_year": 893, "time_original": "留中书月馀不归；具体起止未载", "dynasty": "唐", "description": "昭宗命杜让能留中书筹划调度，一个多月不回家。崔昭纬暗结邠岐，充耳目，杜朝发言二镇夕知。", "phases": [], "location_name": "京师、中书、邠岐", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "d8160975-3536-572e-aaec-7da7f935076d"}, {"title": "李茂贞党纠市人，诉君遂并袭二相", "start_year": 893, "end_year": 893, "time_original": "前述筹兵期间；具体日未载", "dynasty": "唐", "description": "李茂贞命其党聚集市人，拦西门君遂马称岐帅无罪、不宜讨；君遂说属宰相事。市人又拦崔昭纬、郑延昌轿，二相说主上专委杜让能、自己不知。市人投瓦石，二相藏民宅才免，丢堂印与朝服。", "phases": [], "location_name": "京师", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "8ca57c14-80af-513b-853b-63d979348b28"}, {"title": "昭宗诛市人首领，京师仍有逃民", "start_year": 893, "end_year": 893, "time_original": "投瓦袭相之后；具体日未载", "dynasty": "唐", "description": "昭宗命捕杀带头闹事者，讨伐意愿更坚定。部分京师居民逃藏山谷，严刑不能禁。", "phases": [], "location_name": "京师、山谷", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "10eba9b9-4281-51bf-ad45-bbef45550430"}, {"title": "李嗣周京西招讨使，李鐬为副", "start_year": 893, "end_year": 893, "time_original": "893年八月", "dynasty": "唐", "description": "朝廷以嗣覃王李嗣周为京西招讨使，神策大将军李鐬为副。", "phases": [], "location_name": "京西", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "431b51fb-9660-5586-abaf-8f2a7ec23a84"}, {"title": "田頵二万攻歙，裴枢守城久不下", "start_year": 893, "end_year": 893, "time_original": "893年八月丙辰开始；久不下", "dynasty": "唐", "description": "杨行密派田頵率宣州二万军攻歙州，歙州刺史裴枢守城，久未攻下。", "phases": [], "location_name": "歙州、宣州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "f26c3ebb-bb27-5daa-b653-8704bd22e323"}, {"title": "歙人请陶雅，杨任刺史、送裴枢还朝", "start_year": 893, "end_year": 893, "time_original": "久攻后；具体日未载", "dynasty": "唐", "description": "《通鉴》评诸将多贪暴、池州团练使陶雅宽厚得民，歙人说若得陶为刺史便听命。杨行密任陶雅为歙州刺史，歙人接纳；陶以礼见裴枢，送其回朝。", "phases": [], "location_name": "歙州、池州、朝廷", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "a6160dc6-dfd9-573e-ae61-ac4024531ba5"}, {"title": "庞师古移兵攻兗，屡破朱瑾", "start_year": 893, "end_year": 893, "time_original": "893年八月条；各次日未载", "dynasty": "唐", "description": "朱全忠命庞师古移军攻兗州，同朱瑾交战，多次击败朱瑾。", "phases": [], "location_name": "兗州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "4836278e-33f8-516c-b9b9-ff650bfd05ec"}, {"title": "钱镠授镇海节度使", "start_year": 893, "end_year": 893, "time_original": "893年九月丁卯", "dynasty": "唐", "description": "朝廷任钱镠为镇海节度使。", "phases": [], "location_name": "镇海", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "9000f14b-abc0-55a1-b11c-75ae20c43064"}, {"title": "李存孝夜袭李存信营，擒孙考老", "start_year": 893, "end_year": 893, "time_original": "893年九月条；具体日未载", "dynasty": "唐", "description": "李存孝夜袭李存信营，俘获奉诚军使孙考老。", "phases": [], "location_name": "邢州战区、李存信营", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "c71566e5-9fc9-59fc-9dc9-e00cb1854de8"}, {"title": "李克用亲围邢，李存孝突击阻筑堑", "start_year": 893, "end_year": 893, "time_original": "夜袭之后；具体日未载", "dynasty": "唐", "description": "李克用亲率军围邢州，掘沟筑垒环城；李存孝时出突击，使沟垒不能筑成。", "phases": [], "location_name": "邢州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "e5ca88c6-c5a3-57ad-b19f-6acf4a21cbcf"}, {"title": "袁奉韬密劝李存孝停攻，十日沟垒成", "start_year": 893, "end_year": 893, "time_original": "筑堑被阻后；停击旬日成", "dynasty": "唐", "description": "河东牙将袁奉韬秘密遣人告诉李存孝，李克用只是等堑成便回晋阳，其他将非其敌、浅堑不足阻之。李存孝相信，停止出击；十日沟垒完成，无处越逃，李存孝陷入困境。", "phases": [], "location_name": "邢州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "624ebfac-093c-5227-abe8-7d3fd0ecc8a0"}, {"title": "邓季筠从围邢逃返，朱使领亲军", "start_year": 893, "end_year": 893, "time_original": "邢州围城时；具体日未载", "dynasty": "唐", "description": "汴将邓季筠跟随李克用攻邢州，轻骑逃回朱全忠处。朱大喜，使他统领亲军。", "phases": [], "location_name": "邢州、汴", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "1e8b00f6-f75c-5c75-b93d-4da0e375b47f"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

